def is_palindrome(s: str) -> bool:
    """
    Determines if a given string of characters is a palindrome.

    :param s: A string consisting of lowercase English letters.
    :return: True if the string is a palindrome, False otherwise.
    """
    def reverse_string(s: str) -> str:
        """
        Reverses the order of characters in the input string.

        :param s: The input string.
        :return: The reversed string.
        """
        return ''.join(char[::-1] for char in s)

    if not s or len(s) % 2 != 0:
        return False

    return reverse_string(s) == reverse_string(reverse_string(s)[::-1])

